contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 unused) public payable {
        require(unused == unused);

        uint256 balBefore = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint256 balAfter = address(c).balance;

        assert(balAfter == 0);
    }

    receive() external payable {}
}

