pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 unused) internal {
        vm.assume(unused == unused);
        uint256 balBefore = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == 0);
    }

    function testFuzz_run(uint256 unused) public {
        _run(unused);
    }

    receive() external payable {}
}
